"""Build reports/phase2/summary.md from the metric JSON files the training runs wrote.

Only numbers present in those files are printed; a missing run is shown as
missing, never filled in.
"""
from __future__ import annotations

import json
from pathlib import Path


def _f(v, nd=4):
    return "—" if v is None else f"{v:.{nd}f}" if isinstance(v, float) else str(v)


def write_summary(reports: Path) -> Path:
    runs = {p.stem: json.loads(p.read_text(encoding="utf-8")) for p in sorted(reports.glob("stage*.json"))}
    L = ["# Phase 2 training summary", "",
         "Generated by `scripts/train_phase2.py` from the JSON files in this folder. "
         "These are the numbers recorded at training time: validation is used for model selection, "
         "**test** and **holdout** are never used for tuning. The full evaluation (figures, per-class "
         "analysis, generalisation tests) is Phase 3.", ""]

    s1 = [r for r in runs.values() if r.get("stage") == 1]
    if s1:
        L += ["## Stage 1: per-flow classifiers (test split)", "",
              "| Model | Split | Features | n feat | Precision | Recall | F1 | FPR | ROC-AUC | Tactic macro-F1 (end-to-end) | Tactic macro-F1 (given attack) | Fit s | Size MB |",
              "|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
        for r in sorted(s1, key=lambda r: (r["split"], r["feature_set"], r["algo"])):
            b, t = r["test"]["binary"], r["test"]
            L.append(f"| {r['algo']} | {r['split']} | {r['feature_set']} | {r['n_features']} | {_f(b['precision'])} | "
                     f"{_f(b['recall'])} | {_f(b['f1'])} | {_f(b['fpr'])} | {_f(b.get('roc_auc'))} | "
                     f"{_f(t['tactic_end_to_end']['macro_f1'])} | {_f(t.get('tactic_given_attack', {}).get('macro_f1'))} | "
                     f"{r['fit_seconds']} | {r['model']['size_mb']} |")
        L += ["", "### Held-out attack classes (never seen in training)", "",
              "| Model | Split | Features | Class | n | Detected as attack | Expected tactic | Tactic correct |",
              "|---|---|---|---|---|---|---|---|"]
        for r in sorted(s1, key=lambda r: (r["split"], r["feature_set"], r["algo"])):
            for cls, h in r["holdout"].items():
                L.append(f"| {r['algo']} | {r['split']} | {r['feature_set']} | {cls} | {h['n']:,} | "
                         f"{_f(h['detected_rate'])} | {h['expected_tactic']} | {_f(h.get('tactic_correct_rate'))} |")
        L.append("")

    s2 = [r for r in runs.values() if r.get("stage") == 2]
    if s2:
        L += ["## Stage 2: temporal model (test = latest 15% of each day)", "",
              "| Cell | Window | Features | Precision | Recall | F1 | FPR | ROC-AUC | Tactic macro-F1 | Fit s |",
              "|---|---|---|---|---|---|---|---|---|---|"]
        for r in s2:
            b = r["test"]["binary"]
            L.append(f"| {r['cell']} | {r['window']} | {r['feature_set']} | {_f(b['precision'])} | {_f(b['recall'])} | "
                     f"{_f(b['f1'])} | {_f(b['fpr'])} | {_f(b.get('roc_auc'))} | {_f(r['test']['tactic']['macro_f1'])} | "
                     f"{r['fit_seconds']} |")
        L += ["", "Per-day test results:", "", "| Features | Day | n | Attacks | Recall | FPR |", "|---|---|---|---|---|---|"]
        for r in s2:
            for sl, v in r["test_per_slice"].items():
                b = v["binary"]
                L.append(f"| {r['feature_set']} | {sl} | {b['n']:,} | {b['positives']:,} | {_f(b['recall'])} | {_f(b['fpr'])} |")
        L.append("")

    s3 = [r for r in runs.values() if r.get("stage") == 3]
    if s3:
        L += ["## Stage 3: benign-only autoencoder (test split)", "",
              "| Split | Features | Threshold | Val benign FPR | Test precision | Test recall | Test FPR | ROC-AUC | PR-AUC |",
              "|---|---|---|---|---|---|---|---|---|"]
        for r in s3:
            t = r["test"]
            L.append(f"| {r['split']} | {r['feature_set']} | {_f(r['threshold'])} | {_f(r['val_benign_fpr'])} | "
                     f"{_f(t['precision'])} | {_f(t['recall'])} | {_f(t['fpr'])} | {_f(t.get('roc_auc'))} | {_f(t.get('pr_auc'))} |")
        L += ["", "Per source (test): benign false-positive rate and share of attacks flagged.", "",
              "| Features | Source | Benign n | Benign FPR | Attack n | Attacks flagged |", "|---|---|---|---|---|---|"]
        for r in s3:
            for src, v in r["test_per_source"].items():
                L.append(f"| {r['feature_set']} | {src} | {v['benign_n']:,} | {_f(v['benign_fpr'])} | "
                         f"{v['attack_n']:,} | {_f(v['attack_detected'])} |")
        L += ["", "Held-out classes flagged as anomalous:", "", "| Features | Class | n | Flagged |", "|---|---|---|---|"]
        for r in s3:
            for cls, h in r["holdout"].items():
                L.append(f"| {r['feature_set']} | {cls} | {h['n']:,} | {_f(h['detected_rate'])} |")
        L.append("")

    lab = reports / "lab_scores_summary.json"
    if lab.exists():
        s = json.loads(lab.read_text(encoding="utf-8"))
        L += ["## Real lab flows (lab-compatible models)", "",
              f"{s['rows']} real conversations, **{s['attacks']} attack**. With a single attack this shows the "
              "models run on real lab data end to end; it cannot support any precision/recall claim. "
              "Per-flow scores: `lab_scores.csv`.", "",
              "| Model | Flagged | TP | FP | FN | TN |", "|---|---|---|---|---|---|"]
        for name, m in s["models"].items():
            L.append(f"| {name} | {m['tp'] + m['fp']} | {m['tp']} | {m['fp']} | {m['fn']} | {m['tn']} |")
        L.append("")

    out = reports / "summary.md"
    reports.mkdir(parents=True, exist_ok=True)
    out.write_text("\n".join(L), encoding="utf-8")
    return out
